import { SnippetRepository } from 'app/features/template/snippet/repository/snippet-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';
import { Snippet } from 'app/features/template/snippet/model/snippet.model';
import { Component, inject } from '@angular/core';

@Component({ selector: 'snippet-view-enable-selection-action', standalone: false, template: '' })
export class SnippetViewEnableSelectionActionComponent extends ConfirmSelectionAction<Snippet> {
  readonly name = 'enableSelection';
  protected readonly scope = 'template/snippet';
  protected readonly repository = inject(SnippetRepository);

  protected override appliesTo(items: Snippet[]) {
    return items.every((item) => item.enabled !== true) && true;
  }
  protected runSelection(items: Snippet[]) {
    return this.repository.enableSelection({ uids: items.map((item) => item.uid) });
  }
}
